// Process news articles
const articles = $input.all();
const processed = [];

for (const item of articles) {
  const article = item.json;
  const contentHash = require('crypto').createHash('sha256')
    .update(article.title + article.description)
    .digest('hex');

  processed.push({
    article_id: require('uuid').v4(),
    source: 'BLOOMBERG_HT',
    url: article.link,
    title: article.title,
    summary: article.description,
    body: null,
    author: article.creator,
    published_at: article.pubDate,
    ingested_at: new Date().toISOString(),
    language: 'tr',
    content_hash: contentHash
  });
}

return processed.map(a => ({ json: a }));
